PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, nickname TEXT NOT NULL UNIQUE COLLATE NOCASE, adult_confirmed INTEGER NOT NULL CHECK(adult_confirmed=1), avatar TEXT NOT NULL DEFAULT '{"hair":0,"top":0,"bottom":0,"shoes":0,"accessory":0}', created_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS crews (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), invitation_code TEXT NOT NULL UNIQUE, created_at_ms INTEGER NOT NULL, region TEXT NOT NULL DEFAULT '', pace_label TEXT NOT NULL DEFAULT '자유 페이스');
CREATE TABLE IF NOT EXISTS crew_members (crew_id TEXT NOT NULL REFERENCES crews(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','dj','member')), PRIMARY KEY(crew_id,user_id));
CREATE INDEX IF NOT EXISTS crew_members_user_idx ON crew_members(user_id);
CREATE TABLE IF NOT EXISTS parties (id TEXT PRIMARY KEY, crew_id TEXT NOT NULL REFERENCES crews(id), creator_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, starts_at_ms INTEGER NOT NULL, meeting_point TEXT NOT NULL, distance_km REAL NOT NULL, pace_min_per_km REAL NOT NULL DEFAULT 6, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 2 AND 20), status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','cancelled')), kind TEXT NOT NULL DEFAULT 'local' CHECK(kind IN ('local','remote')), latitude REAL, longitude REAL, pace_label TEXT NOT NULL DEFAULT '자유 페이스');
CREATE TABLE IF NOT EXISTS party_members (party_id TEXT NOT NULL REFERENCES parties(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(party_id,user_id));
CREATE INDEX IF NOT EXISTS party_members_user_idx ON party_members(user_id);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, scope_type TEXT NOT NULL CHECK(scope_type IN ('crew','party')), scope_id TEXT NOT NULL, sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('chat','announcement')), created_at_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS messages_scope_idx ON messages(scope_type,scope_id,id);
CREATE TABLE IF NOT EXISTS blocks (blocker_id TEXT NOT NULL REFERENCES users(id), blocked_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id <> blocked_id));
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), party_id TEXT REFERENCES parties(id), started_at_ms INTEGER NOT NULL, ended_at_ms INTEGER, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','finalized')), distance_m REAL NOT NULL DEFAULT 0, active_duration_s REAL NOT NULL DEFAULT 0, elapsed_duration_s REAL NOT NULL DEFAULT 0, reward_points INTEGER NOT NULL DEFAULT 0, deleted_at_ms INTEGER);
CREATE INDEX IF NOT EXISTS runs_user_idx ON runs(user_id,started_at_ms);
CREATE TABLE IF NOT EXISTS track_points (run_id TEXT NOT NULL REFERENCES runs(id), seq INTEGER NOT NULL CHECK(seq>=0), latitude REAL NOT NULL, longitude REAL NOT NULL, recorded_at_ms INTEGER NOT NULL, accuracy_m REAL NOT NULL, altitude_m REAL, segment INTEGER NOT NULL DEFAULT 0 CHECK(segment>=0), PRIMARY KEY(run_id,seq));
CREATE TABLE IF NOT EXISTS ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), run_id TEXT UNIQUE REFERENCES runs(id), item_id TEXT, delta INTEGER NOT NULL, created_at_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ledger_user_time_idx ON ledger(user_id,created_at_ms);
CREATE TABLE IF NOT EXISTS owned_items (user_id TEXT NOT NULL REFERENCES users(id), item_id TEXT NOT NULL, PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS presence (user_id TEXT PRIMARY KEY REFERENCES users(id), run_id TEXT NOT NULL REFERENCES runs(id), scope_type TEXT NOT NULL CHECK(scope_type IN ('crew','party','pilot')), scope_id TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, updated_at_ms INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS presence_scope_idx ON presence(scope_type,scope_id,expires_at_ms);
CREATE TABLE IF NOT EXISTS music_leases (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), scope_type TEXT NOT NULL, scope_id TEXT NOT NULL, session_id TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS music_lease_room_idx ON music_leases(scope_type,scope_id,expires_at_ms);
